package cli

import (
	"maps"
	"os"
	"regexp"
	"strings"
	"testing"

	"github.com/rancher/rancher-cli/internal/runtime"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// dryRunDisplayIdentityGenericCommands is the reviewed, closed-world set of
// mutating commands, named explicitly (not generated by kind), whose Effect
// and committed Text come ENTIRELY from the three shared generic planners
// (engine.PlanCreate, engine.PlanUpdate, resources.PlanFromFetched) or a
// tested wrapper that only appends to the Result/Effect those planners
// already returned (membership.go's indented context line, secret.go's
// project-scoped propagation warning, provisioning's stamped-identity and
// version warnings, the creator annotation warning of `create project` and
// `create resource`) - none of which ever assigns to DisplayKind or
// DisplayName. Those three planners set both fields unconditionally:
// DisplayKind from a kind-table Name (internal/engine/kinds's
// TestAllKindsHaveNonEmptyName proves that value is never empty for any
// row), DisplayName from a real object's returned name. So the identity
// invariant holds by construction for every command in this set - no
// per-command render test has to reprove it individually.
//
// The generated "patch <kind>"/"delete <kind>" families (resources.NewPatch,
// resources.NewDelete, and every guard wrapping them - guarded_delete.go,
// managementtoken.go's refuse/guard commands, provisioning/deletecluster.go)
// are the same by-construction case and are matched by name prefix in
// TestDryRunDisplayIdentityClosedWorldConformance below, not listed here one
// kind at a time: every guard only ever appends to Effect.Warnings, never
// touches DisplayKind/DisplayName.
var dryRunDisplayIdentityGenericCommands = map[string]bool{
	"cluster clear-autoscaling":  true,
	"cluster pause-autoscaling":  true,
	"cluster resume-autoscaling": true,
	"cluster scale":              true,
	"cluster set-autoscaling":    true,
	"create cluster":             true,
	"create kubeconfig":          true,
	"create machine-config":      true,
	"create namespace":           true,
	"create oidc-client":         true,
	"create project":             true,
	"create resource":            true,
	"create secret":              true,
	"create token":               true,
	"oidc-client add-secret":     true,
	"oidc-client remove-secret":  true,
	"oidc-client rotate-secret":  true,
	"project add-namespace":      true,
	"project remove-namespace":   true,
}

// dryRunBespokeEffectCommands is the reviewed, closed-world set of mutating
// commands whose Plan constructs or overrides a safety.Effect's
// DisplayKind/DisplayName directly - bypassing the generic planners'
// by-construction guarantee above. Each value names the test(s) that
// exercise the command's own Plan/exec end to end and assert
// DisplayKind/DisplayName are non-empty and that the committed success
// identity never carries the dry-run preview's "*" marker. A future
// bespoke command that hand-builds or rewrites an Effect's identity fields
// must be added here (or reclassified into the generic set above, if it
// truly never touches those fields) before it ships, or this test fails.
var dryRunBespokeEffectCommands = map[string]string{
	"grant":  "internal/engine/rbac/grant_test.go: TestGrantGlobalScope, TestGrantClusterScope, TestGrantProjectUserByID assert DisplayKind on every scope; TestGrantCommittedIdentityNeverCarriesPreviewWildcard asserts the committed text never carries \"*\"",
	"revoke": "internal/engine/rbac/revoke_test.go: TestRevokeSingleRole and TestRevokeAllRolesAtScope assert DisplayKind/DisplayName and the exact per-binding committed text",
	"create user": "internal/engine/user/create_test.go: TestCreatePlanDisplayIdentity asserts DisplayKind/DisplayName; " +
		"TestCreateExecuteRedactsSecretPayloadAndReturnsRealCommittedIdentity asserts the committed identity is the real server-assigned name, never the dry-run preview placeholder",
	"create password-change-request": "internal/engine/extres/createpasswordchangerequest_test.go: TestCreatePasswordChangeRequestPlanDisplayIdentity asserts DisplayKind/DisplayName (the request resource itself carries no name, so DisplayName names the target user)",
	"app install":                    "internal/engine/catalog/install_test.go: TestInstallPlanDisplayIdentity asserts DisplayKind/DisplayName (the release name) and that the committed identity never carries the dry-run preview's \"*\" marker",
	"app uninstall":                  "internal/engine/catalog/uninstall_test.go: TestUninstallPlanDisplayIdentity asserts DisplayKind/DisplayName (the release name) and that the committed identity never carries the dry-run preview's \"*\" marker",
}

// dryRunGenericFamilyPrefixes names the two generated command families
// whose every member (one per kind-table row) is covered by construction,
// per dryRunDisplayIdentityGenericCommands' doc - matched by prefix so this
// file does not have to enumerate all ~80 individual kind names.
var dryRunGenericFamilyPrefixes = []string{"patch ", "delete "}

// classifyDryRunDisplayIdentity reports whether name is accounted for by
// the generic-by-construction set (explicit name, or a generated
// patch/delete family member) or the reviewed bespoke inventory, or
// neither (unclassified - a conformance failure).
func classifyDryRunDisplayIdentity(name string) (generic, bespoke bool) {
	if dryRunDisplayIdentityGenericCommands[name] {
		return true, false
	}
	for _, prefix := range dryRunGenericFamilyPrefixes {
		if strings.HasPrefix(name, prefix) {
			return true, false
		}
	}
	_, ok := dryRunBespokeEffectCommands[name]
	return false, ok
}

// TestDryRunDisplayIdentityClosedWorldConformance walks every registered
// Mutating command bidirectionally against the two reviewed inventories
// above: every registered mutating command must classify as either
// generic-by-construction or a reviewed bespoke entry, and every reviewed
// entry must name a command the registry actually has. A future mutating
// command - generic or bespoke - that ships without being classified here
// fails this test, the same closed-world posture
// TestOutputShapeClosedWorldConformance and
// TestDeliveryOnceOnlyClosedWorldConformance already hold the rest of the
// surface to.
func TestDryRunDisplayIdentityClosedWorldConformance(t *testing.T) {
	t.Parallel()
	wr, err := buildWiredRegistry("v-test", nil)
	require.NoError(t, err)

	seen := map[string]bool{}
	for _, c := range wr.reg.Commands() {
		d := c.Describe()
		if d.CommandType != runtime.Mutating {
			continue
		}
		seen[d.Name] = true

		generic, bespoke := classifyDryRunDisplayIdentity(d.Name)
		assert.True(t, generic || bespoke,
			"mutating command %q is not classified in the dry-run display-identity inventory - "+
				"add it to dryRunDisplayIdentityGenericCommands (built purely from the shared generic "+
				"planners) or dryRunBespokeEffectCommands (naming the test that verifies its "+
				"DisplayKind/DisplayName) before it ships", d.Name)

		// The generated "patch <kind>"/"delete <kind>" families register
		// their command Name as the literal prefix plus the kind row's own
		// Name field (patch.go, delete.go) - the exact value they pass as
		// DisplayKind. A non-empty suffix here is therefore real evidence
		// that DisplayKind is non-empty for every one of these commands,
		// not a restatement of the classification above.
		for _, prefix := range dryRunGenericFamilyPrefixes {
			if kindName, ok := strings.CutPrefix(d.Name, prefix); ok {
				assert.NotEmpty(t, kindName, "command %q must carry a non-empty kind name after %q - its DisplayKind would be empty", d.Name, prefix)
			}
		}
	}

	for name := range dryRunDisplayIdentityGenericCommands {
		assert.True(t, seen[name], "dryRunDisplayIdentityGenericCommands entry %q names no registered mutating command - remove it or check the spelling", name)
	}
	for name := range dryRunBespokeEffectCommands {
		assert.True(t, seen[name], "dryRunBespokeEffectCommands entry %q names no registered mutating command - remove it or check the spelling", name)
	}
}

// TestDryRunDisplayIdentityClosedWorldConformanceCatchesAnUnclassifiedCommand
// proves the forward direction actually fails when a mutating command is
// absent from BOTH reviewed inventories: it trims "revoke" - a real
// registered command - out of a copy of the actual bespoke inventory,
// installs that copy in place of the package var, and runs the real
// classifyDryRunDisplayIdentity/registry walk that
// TestDryRunDisplayIdentityClosedWorldConformance itself relies on. This
// must not run in parallel with tests that read the package-level
// inventories.
func TestDryRunDisplayIdentityClosedWorldConformanceCatchesAnUnclassifiedCommand(t *testing.T) {
	wr, err := buildWiredRegistry("v-test", nil)
	require.NoError(t, err)

	original := dryRunBespokeEffectCommands
	trimmed := map[string]string{}
	maps.Copy(trimmed, original)
	delete(trimmed, "revoke")
	dryRunBespokeEffectCommands = trimmed
	t.Cleanup(func() { dryRunBespokeEffectCommands = original })

	var unclassified bool
	for _, c := range wr.reg.Commands() {
		d := c.Describe()
		if d.CommandType != runtime.Mutating || d.Name != "revoke" {
			continue
		}
		generic, bespoke := classifyDryRunDisplayIdentity(d.Name)
		unclassified = !generic && !bespoke
	}
	assert.True(t, unclassified, "removing a bespoke inventory entry must leave the real classifier unable to classify that command")
}

// TestDryRunDisplayIdentityClosedWorldConformanceCatchesAStaleEntry proves
// the reverse direction: it adds a fabricated entry naming a command the
// registry does not have to a copy of the real bespoke inventory, installs
// it in place of the package var, and runs the same seen-membership check
// TestDryRunDisplayIdentityClosedWorldConformance's second loop performs
// against the real registry. This must not run in parallel with tests that
// read the package-level inventories.
func TestDryRunDisplayIdentityClosedWorldConformanceCatchesAStaleEntry(t *testing.T) {
	wr, err := buildWiredRegistry("v-test", nil)
	require.NoError(t, err)

	original := dryRunBespokeEffectCommands
	withStale := map[string]string{}
	maps.Copy(withStale, original)
	withStale["grant (renamed)"] = "stale entry for the reverse-direction proof"
	dryRunBespokeEffectCommands = withStale
	t.Cleanup(func() { dryRunBespokeEffectCommands = original })

	seen := map[string]bool{}
	for _, c := range wr.reg.Commands() {
		seen[c.Describe().Name] = true
	}

	var found bool
	for name := range dryRunBespokeEffectCommands {
		if !seen[name] {
			found = true
		}
	}
	assert.True(t, found, "a stale inventory entry naming an unregistered command must be detectable")
}

// bespokeTestReferencePattern extracts a dryRunBespokeEffectCommands value's
// file path (everything before the first ": ") and the Test function names
// it cites, so TestDryRunBespokeEffectCommandsCiteRealTests can check both
// still exist. It intentionally does not try to parse the free-form prose
// between names.
var (
	bespokeTestReferenceFile = regexp.MustCompile(`^([^:]+\.go):`)
	bespokeTestReferenceFunc = regexp.MustCompile(`\bTest[A-Za-z0-9_]+\b`)
)

// TestDryRunBespokeEffectCommandsCiteRealTests keeps
// dryRunBespokeEffectCommands' doc-string test references from rotting: each
// value names a file and one or more Test functions that are supposed to
// assert the command's DisplayKind/DisplayName end to end. Renaming or
// deleting one of those functions would otherwise silently stop proving the
// claim this file's own review process depends on.
func TestDryRunBespokeEffectCommandsCiteRealTests(t *testing.T) {
	t.Parallel()
	for command, ref := range dryRunBespokeEffectCommands {
		fileMatch := bespokeTestReferenceFile.FindStringSubmatch(ref)
		if !assert.NotNil(t, fileMatch, "dryRunBespokeEffectCommands[%q] must start with \"<path>.go: \"", command) {
			continue
		}
		path := docPath(t, fileMatch[1])
		src, err := os.ReadFile(path)
		require.NoErrorf(t, err, "dryRunBespokeEffectCommands[%q] cites %s, which does not exist", command, fileMatch[1])
		names := bespokeTestReferenceFunc.FindAllString(ref, -1)
		if !assert.NotEmpty(t, names, "dryRunBespokeEffectCommands[%q] names no Test function", command) {
			continue
		}
		for _, name := range names {
			assert.Regexp(t, regexp.MustCompile(`func `+name+`\(`), string(src),
				"dryRunBespokeEffectCommands[%q] cites %s's %s, which no longer exists there", command, fileMatch[1], name)
		}
	}
}
